import json, glob, os, datetime, collections
base='alerts'
alerts=collections.defaultdict(list)
for path in sorted(glob.glob(os.path.join(base,'alerts_at_*.json'))):
    data=json.load(open(path))
    for a in data.get('alerts',[]):
        ns=a.get('labels',{}).get('namespace')
        if ns!='otel-demo':
            continue
        name=a['labels'].get('alertname','unknown')
        ts=a.get('activeAt') or a.get('startsAt')
        if ts:
            dt=datetime.datetime.fromisoformat(ts.replace('Z','+00:00'))
        else:
            dt=None
        alerts[name].append({'state':a.get('state'), 'ts':dt, 'path':path})

for name, items in alerts.items():
    states=[i['state'] for i in items]
    first=min((i['ts'] for i in items if i['ts']), default=None)
    last=max((i['ts'] for i in items if i['ts']), default=None)
    print(name, len(items), 'states', set(states), 'first', first, 'last', last)
